//! The home hero's ASCII portrait (generated by `just portrait`).
//!
//! Two stacked layers of real text: dim ASCII underneath, and a shaded-block
//! version on top that only shows through a soft lens following the pointer
//! (a CSS mask driven by `--mx`/`--my`). Characters under the pointer
//! scramble for a moment as it moves, and on load the face decodes in. All
//! of that is added after hydration; the server-rendered text is the
//! no-JavaScript version, and reduced motion keeps only the lens.

use leptos::prelude::*;

const BASE: &str = include_str!("../../ascii/portrait.txt");
const LENS: &str = include_str!("../../ascii/portrait-lens.txt");

#[component]
pub fn AsciiPortrait(#[prop(into)] label: String) -> impl IntoView {
    let root = NodeRef::<leptos::html::Div>::new();
    let base = NodeRef::<leptos::html::Pre>::new();

    #[cfg(feature = "hydrate")]
    {
        // Dropped with the component, which detaches the listeners.
        let listeners = StoredValue::new_local(None::<live::Listeners>);
        Effect::new(move |done: Option<bool>| {
            if done == Some(true) {
                return true;
            }
            let (Some(root), Some(base)) = (root.get(), base.get()) else {
                return false;
            };
            listeners.set_value(live::start(root.into(), base.into()));
            true
        });
    }

    view! {
        <div class="ascii" role="img" aria-label=label node_ref=root>
            <pre class="ascii__base" aria-hidden="true" node_ref=base>
                {BASE.lines().map(|l| view! { <span>{l}"\n"</span> }).collect_view()}
            </pre>
            <pre class="ascii__lens" aria-hidden="true">{LENS}</pre>
        </div>
    }
}

#[cfg(feature = "hydrate")]
mod live {
    use std::cell::RefCell;
    use std::rc::Rc;

    use wasm_bindgen::JsCast;
    use wasm_bindgen::prelude::*;
    use web_sys::{HtmlElement, PointerEvent};

    use super::BASE;

    /// Characters a scrambling cell flickers through.
    const NOISE: &[char] = &[
        '.', ':', '-', '=', '+', '*', '#', '%', '@', '/', '\\', '<', '>',
    ];
    /// Pointer influence, in columns (rows are scaled by the cell aspect).
    const RADIUS: f32 = 7.0;
    const CELL_ASPECT: f32 = 0.6;

    struct State {
        rows: Vec<Vec<char>>,
        spans: Vec<HtmlElement>,
        /// Per cell: scrambling until this time (ms), or 0.
        until: Vec<f64>,
        shown: Vec<char>,
        dirty: Vec<bool>,
        pointer: Option<(f32, f32)>,
        moved: bool,
        running: bool,
        seed: u32,
    }

    impl State {
        fn cols(&self) -> usize {
            self.rows.first().map_or(0, Vec::len)
        }

        fn rand(&mut self) -> f32 {
            self.seed ^= self.seed << 13;
            self.seed ^= self.seed >> 17;
            self.seed ^= self.seed << 5;
            (self.seed & 0xffff) as f32 / 65535.0
        }

        fn noise(&mut self) -> char {
            NOISE[(self.rand() * NOISE.len() as f32) as usize % NOISE.len()]
        }

        /// Start a cell scrambling (ink only: the background stays empty).
        fn scramble(&mut self, r: usize, c: usize, until: f64) {
            let cols = self.cols();
            if self.rows[r][c] == ' ' {
                return;
            }
            let i = r * cols + c;
            if self.until[i] < until {
                self.until[i] = until;
            }
            self.shown[i] = self.noise();
            self.dirty[r] = true;
        }

        /// One frame: scatter noise round the pointer, flicker the live
        /// cells, settle the expired ones, write back the rows that changed.
        /// Returns whether anything is still moving.
        fn tick(&mut self, now: f64) -> bool {
            let cols = self.cols();
            if let (Some((px, py)), true) = (self.pointer, self.moved) {
                self.moved = false;
                let (r0, r1) = (
                    (py - RADIUS * CELL_ASPECT).floor().max(0.0) as usize,
                    ((py + RADIUS * CELL_ASPECT).ceil() as usize).min(self.rows.len()),
                );
                let (c0, c1) = (
                    (px - RADIUS).floor().max(0.0) as usize,
                    ((px + RADIUS).ceil() as usize).min(cols),
                );
                for r in r0..r1 {
                    for c in c0..c1 {
                        let dx = (c as f32 + 0.5 - px) / RADIUS;
                        let dy = (r as f32 + 0.5 - py) / (RADIUS * CELL_ASPECT);
                        let d = (dx * dx + dy * dy).sqrt();
                        if d < 1.0 && self.rand() < 0.4 * (1.0 - d) * (1.0 - d) {
                            let life = 90.0 + self.rand() as f64 * 160.0;
                            self.scramble(r, c, now + life);
                        }
                    }
                }
            }
            let mut alive = false;
            for i in 0..self.until.len() {
                if self.until[i] == 0.0 {
                    continue;
                }
                let r = i / cols;
                if now >= self.until[i] {
                    self.until[i] = 0.0;
                    self.shown[i] = self.rows[r][i % cols];
                    self.dirty[r] = true;
                } else {
                    alive = true;
                    if self.rand() < 0.35 {
                        self.shown[i] = self.noise();
                        self.dirty[r] = true;
                    }
                }
            }
            for r in 0..self.rows.len() {
                if std::mem::take(&mut self.dirty[r]) {
                    let mut line: String = self.shown[r * cols..(r + 1) * cols].iter().collect();
                    line.push('\n');
                    self.spans[r].set_text_content(Some(&line));
                }
            }
            alive || self.moved
        }
    }

    fn now() -> f64 {
        web_sys::window()
            .and_then(|w| w.performance())
            .map_or(0.0, |p| p.now())
    }

    fn reduced_motion() -> bool {
        web_sys::window()
            .and_then(|w| {
                w.match_media("(prefers-reduced-motion: reduce)")
                    .ok()
                    .flatten()
            })
            .is_some_and(|m| m.matches())
    }

    /// A requestAnimationFrame callback.
    type Frame = Closure<dyn FnMut(f64)>;

    /// Run frames until the state settles.
    fn run(state: Rc<RefCell<State>>) {
        if std::mem::replace(&mut state.borrow_mut().running, true) {
            return;
        }
        let frame: Rc<RefCell<Option<Frame>>> = Rc::new(RefCell::new(None));
        let again = frame.clone();
        *frame.borrow_mut() = Some(Closure::new(move |t: f64| {
            let busy = state.borrow_mut().tick(t);
            if busy {
                if let (Some(w), Some(f)) = (web_sys::window(), again.borrow().as_ref()) {
                    let _ = w.request_animation_frame(f.as_ref().unchecked_ref());
                }
            } else {
                state.borrow_mut().running = false;
                again.borrow_mut().take();
            }
        }));
        if let (Some(w), Some(f)) = (web_sys::window(), frame.borrow().as_ref()) {
            let _ = w.request_animation_frame(f.as_ref().unchecked_ref());
        }
    }

    pub fn start(root: HtmlElement, base: HtmlElement) -> Option<Listeners> {
        let rows: Vec<Vec<char>> = BASE.lines().map(|l| l.chars().collect()).collect();
        let cols = rows.first().map_or(0, Vec::len);
        let children = base.children();
        let spans: Vec<HtmlElement> = (0..children.length())
            .filter_map(|i| children.item(i)?.dyn_into().ok())
            .collect();
        if spans.len() != rows.len() || cols == 0 {
            return None;
        }
        let shown: Vec<char> = rows.iter().flatten().copied().collect();
        let state = Rc::new(RefCell::new(State {
            dirty: vec![false; rows.len()],
            until: vec![0.0; shown.len()],
            shown,
            rows,
            spans,
            pointer: None,
            moved: false,
            running: false,
            seed: (now() as u32) | 1,
        }));
        let motion = !reduced_motion();
        let _ = root.class_list().add_1("ascii--live");

        // Decode in: every inked cell scrambles, then settles in a sweep
        // from left to right.
        if motion {
            let t = now();
            let mut s = state.borrow_mut();
            let n = s.rows.len();
            for r in 0..n {
                for c in 0..cols {
                    let at = t + 120.0 + (c as f64 / cols as f64) * 650.0 + s.rand() as f64 * 280.0;
                    s.scramble(r, c, at);
                }
            }
            drop(s);
            run(state.clone());
        }

        // The lens follows the pointer; the scramble trails it.
        let on_move = {
            let (root, state) = (root.clone(), state.clone());
            Closure::<dyn FnMut(PointerEvent)>::new(move |e: PointerEvent| {
                let rect = root.get_bounding_client_rect();
                let (x, y) = (
                    e.client_x() as f64 - rect.left(),
                    e.client_y() as f64 - rect.top(),
                );
                let style = root.style();
                let _ = style.set_property("--mx", &format!("{x:.0}px"));
                let _ = style.set_property("--my", &format!("{y:.0}px"));
                let _ = root.class_list().add_1("ascii--on");
                if motion && rect.width() > 0.0 {
                    let mut s = state.borrow_mut();
                    let cols = s.cols() as f64;
                    let rows = s.rows.len() as f64;
                    s.pointer = Some((
                        (x / rect.width() * cols) as f32,
                        (y / rect.height() * rows) as f32,
                    ));
                    s.moved = true;
                    drop(s);
                    run(state.clone());
                }
            })
        };
        let on_leave = {
            let root = root.clone();
            Closure::<dyn FnMut(PointerEvent)>::new(move |e: PointerEvent| {
                let touch = e.pointer_type() == "touch";
                // A mouse button coming up isn't the pointer leaving.
                if e.type_() == "pointerup" && !touch {
                    return;
                }
                // A finger lifts straight away; let the lens linger a beat.
                let delay = if touch { 900 } else { 0 };
                let root = root.clone();
                let off = Closure::once_into_js(move || {
                    let _ = root.class_list().remove_1("ascii--on");
                });
                if let Some(w) = web_sys::window() {
                    let _ = w.set_timeout_with_callback_and_timeout_and_arguments_0(
                        off.unchecked_ref(),
                        delay,
                    );
                }
            })
        };
        let _ =
            root.add_event_listener_with_callback("pointermove", on_move.as_ref().unchecked_ref());
        let _ =
            root.add_event_listener_with_callback("pointerdown", on_move.as_ref().unchecked_ref());
        for ev in ["pointerleave", "pointercancel", "pointerup"] {
            let _ = root.add_event_listener_with_callback(ev, on_leave.as_ref().unchecked_ref());
        }
        Some(Listeners {
            root,
            on_move,
            on_leave,
        })
    }

    /// Owns the pointer handlers; dropping it (the component unmounting)
    /// detaches them.
    pub struct Listeners {
        root: HtmlElement,
        on_move: Closure<dyn FnMut(PointerEvent)>,
        on_leave: Closure<dyn FnMut(PointerEvent)>,
    }

    impl Drop for Listeners {
        fn drop(&mut self) {
            for ev in ["pointermove", "pointerdown"] {
                let _ = self
                    .root
                    .remove_event_listener_with_callback(ev, self.on_move.as_ref().unchecked_ref());
            }
            for ev in ["pointerleave", "pointercancel", "pointerup"] {
                let _ = self.root.remove_event_listener_with_callback(
                    ev,
                    self.on_leave.as_ref().unchecked_ref(),
                );
            }
        }
    }
}
